CREATE OR REPLACE FUNCTION get_excursion_time(p_shipment_code text)
RETURNS numeric AS $$
DECLARE
    excursion_time numeric;
BEGIN
    SELECT em.env_metrics->'temperature'->>'excursion_duration_min'::numeric
    INTO excursion_time
    FROM shipments s
    JOIN environmentalmonitoring em ON s.reckey = em.reckeylink
    WHERE s.shiptok = p_shipment_code;

    RETURN COALESCE(excursion_time, 0);
END;
$$ LANGUAGE plpgsql;

